perform set_config('app.session_id',internal_session::text,true);select*into r from public.hotel_inquiry_command_v1(c,h,inq,'START_ANSWER',v,jsonb_build_object('reason','후임 요청 답변'),repeat('I',43),gen_random_uuid(),'inq-successor-start','POST','/api/hotels/'||h||'/inquiries/'||inq||'/transitions','successor-start-hash',gen_random_uuid(),gen_random_uuid());v:=(r.result_snapshot->>'version')::int;select*into r from public.hotel_inquiry_command_v1(c,h,inq,'ADD_PUBLIC_MESSAGE',v,jsonb_build_object('body','후임 소유주 공개답변','visibility','PUBLIC'),repeat('I',43),gen_random_uuid(),'inq-successor-public','POST','/api/hotels/'||h||'/inquiries/'||inq||'/messages','successor-public-hash',gen_random_uuid(),gen_random_uuid());v:=(r.result_snapshot->>'version')::int;select*into r from public.hotel_inquiry_command_v1(c,h,inq,'MARK_ANSWERED',v,jsonb_build_object('reason','후임 소유주 답변완료'),repeat('I',43),gen_random_uuid(),'inq-successor-answered','POST','/api/hotels/'||h||'/inquiries/'||inq||'/transitions','successor-answered-hash',gen_random_uuid(),gen_random_uuid());v:=(r.result_snapshot->>'version')::int;if not exists(select 1 from public.hotel_inquiry_notifications where company_id=c and inquiry_id=inq and recipient_user_id=successor_id and inquiry_version=v and event_code='HOTEL_INQUIRY_MARK_ANSWERED')or exists(select 1 from public.hotel_inquiry_notifications where company_id=c and inquiry_id=inq and recipient_user_id=owner_id and inquiry_version=v and event_code='HOTEL_INQUIRY_MARK_ANSWERED')then raise exception'successor notification handoff failed';end if;
insert into public.user_groups(id,company_id,name,status,created_by)values('1a524000-0000-4000-8000-000000000001',c,'문의 비활성 알림 검증 그룹','ACTIVE',internal_id);insert into public.user_group_memberships(id,company_id,group_id,user_id,valid_from,granted_by,reason)values('1a525000-0000-4000-8000-000000000001',c,'1a524000-0000-4000-8000-000000000001',internal_id,statement_timestamp()-interval'1 day',internal_id,'비활성 구성원 알림 검증');update public.hotel_inquiries set routing_group_id='1a524000-0000-4000-8000-000000000001' where id=inq;update public.users set status='INACTIVE'where company_id=c and id=internal_id;perform set_config('app.session_id',successor_session::text,true);select*into r from public.hotel_inquiry_command_v1(c,h,inq,'CLOSE',v,jsonb_build_object('reason','비활성 수신자 검증'),repeat('S',43),gen_random_uuid(),'inq-inactive-recipient-close','POST','/api/hotels/'||h||'/inquiries/'||inq||'/transitions','inactive-recipient-close-hash',gen_random_uuid(),gen_random_uuid());if r.command_status<>'UPDATED'then raise exception'inactive recipient close failed: %',r.command_status;end if;v:=(r.result_snapshot->>'version')::int;if exists(select 1 from public.hotel_inquiry_notifications where company_id=c and inquiry_id=inq and inquiry_version=v and recipient_user_id=internal_id)then raise exception'inactive assignee/group member notified';end if;update public.user_groups set status='INACTIVE'where company_id=c and id='1a524000-0000-4000-8000-000000000001';update public.hotel_inquiries set status='ANSWERED',answered_at=statement_timestamp(),closed_at=null,reopen_until=null,version=version+1 where id=inq returning version into v;select*into r from public.hotel_inquiry_command_v1(c,h,inq,'CLOSE',v,jsonb_build_object('reason','비활성 그룹 검증'),repeat('S',43),gen_random_uuid(),'inq-inactive-group-close','POST','/api/hotels/'||h||'/inquiries/'||inq||'/transitions','inactive-group-close-hash',gen_random_uuid(),gen_random_uuid());v:=(r.result_snapshot->>'version')::int;if exists(select 1 from public.hotel_inquiry_notifications where company_id=c and inquiry_id=inq and inquiry_version=v and recipient_user_id=internal_id)then raise exception'inactive group notified';end if;
